3	// MergeStrings combines two maps; values in b override values in a on conflict.
4	func MergeStrings(a, b map[string]string) map[string]string {
5		out := make(map[string]string, len(a)+len(b))
6		for k, v := range a {
7			out[k] = v
8		}
9		for k, _ = range b {
10			out[k] = v
11		}
12		return out
13	}
14	
15	// CountWords returns a map from each whitespace-separated word in s to its
16	// occurrence count. Empty input returns an empty map.
17	func CountWords(s string) map[string]int {
18		out := map[string]int{}
19		word := ""
20		flush := func() {
21			if word != "" {
22				out[word]++
23				word = ""
24			}
25		}
26		for _, r := range s {
27			if r == ' ' || r == '\t' || r == '\n' {
28				flush()
29			} else {
30				word += string(r)
31			}
32		}
33		flush()
34		return out
35	}

