17	func CountWords(s string) map[string]int {
18		out := map[string]int{}
19		word := ""
20		flush := func() {
21			if word != "" {
22				out[word]++
23				word = ""
24			}
25		}
26		for _, r := range s {
27			if r == ' ' || r == '\t' || r == '\n' {
28				flush()
29			} else {
30				word += string(r)
31			}
32		}
33		flush()
34		return out
35	}

