3	import "unicode"
4	
5	// Reverse returns s with its runes in reverse order.
6	func Reverse(s string) string {
7		runes := []rune(s)
8		for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
9			runes[i], runes[j] = runes[j], runes[i]
10		}
11		return string(runes)
12	}
13	
14	// CountVowels returns the number of vowels (a, e, i, o, u, case-insensitive) in s.
15	func CountVowels(s string) int {
16		n := 0
17		for _, r := range s {
18			switch unicode.ToLower(r) {
19			case 'a', 'e', 'i', 'o', 'u':
20				n++
21			}
22		}
23		return n
24	}
25	
26	// IsAnagram reports whether a and b have the same letters (case-insensitive),
27	// ignoring spaces.
28	func IsAnagram(a, b string) bool {
29		count := func(s string) map[rune]int {
30			m := map[rune]int{}
31			for _, r := range s {
32				if r == ' ' {
33					continue
34				}
35				m[unicode.ToLower(r)]++
36			}
37			return m
38		}
39		ca, cb := count(a), count(b)
40		if len(ca) != len(cb) {
41			return false
42		}
43		for k, v := range ca {
44			if cb[k] != v {
45				return false
46			}
47		}
48		return true
49	}

