26	// IsAnagram reports whether a and b have the same letters (case-insensitive),
27	// ignoring spaces.
28	func IsAnagram(a, b string) bool {
29		count := func(s string) map[rune]int {
30			m := map[rune]int{}
31			for _, r := range s {
32				if r == ' ' {
33					continue
34				}
35				m[unicode.ToLower(r)]++
36			}
37			return m
38		}
39		ca, cb := count(a), count(b)
40		if len(ca) != len(cb) {
41			return false
42		}
43		for k, v := range ca {
44			if cb[k] != v {
45				return false
46			}
47		}
48		return true
49	}

